 $tokens=$null;$errors=$null;$null=[Management.Automation.Language.Parser]::ParseInput($guest,[ref]$tokens,[ref]$errors);Need ($errors.Count-eq0) 'Generated paged baseline worker syntax differs.'
 $worker=Join-Path $root 'guest-wrapper.ps1';[IO.File]::WriteAllText($worker,$guest,[Text.UTF8Encoding]::new($false));$workerSha=(Get-FileHash -LiteralPath $worker).Hash.ToLowerInvariant();Save 'worker-config.json' $c
 $session=New-PSSession -VMId $vmId -Credential (Import-Clixml (Join-Path $workspace '.lab\hyperv\win11\secrets\guest-credential.xml'))
 $ready=Invoke-Command -Session $session -ArgumentList $stage,$task -ScriptBlock {param($Stage,$Task) Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';if($env:COMPUTERNAME-cne'N2R-WIN11'-or(Test-Path -LiteralPath $Stage)-or@(Get-ScheduledTask|Where-Object {$_.TaskName-ceq$Task-or($_.TaskName-like'N2R-*'-and$_.State.ToString()-notin@('Ready','Disabled'))}).Count-or@(Get-CimInstance Win32_Process|Where-Object {$_.Name-match'\A(?:ntfs2refs(?:-.+)?|lab-.+)\.exe\z'}).Count){throw 'Fresh idle owning guest stage required.'};$a=Get-Item -LiteralPath 'C:\ntfs2refs';while($null-ne$a){if($a.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Reparse stage ancestry.'};$a=$a.Parent};New-Item -ItemType Directory -Path $Stage|Out-Null;@{stage=$Stage;utc=[DateTime]::UtcNow.ToString('o')}};Save 'ready.json' $ready
 foreach($pin in @($pins)+@($tools)+@($c.additional)){Copy-Item -LiteralPath $pin.host -Destination (Join-Path $stage $pin.name) -ToSession $session};Copy-Item -LiteralPath $worker -Destination (Join-Path $stage 'wrapper.ps1') -ToSession $session
 HostGuard
 Save 'dispatch.json' @{schema_version=1;kind='paged-full-source-baseline-dispatch';run=$run;source_commit=$SourceCommit;guest_stage=$stage;task_name=$task;wrapper_sha256=$workerSha;expected_parent=$ExpectedParent;checkpoint_ids=$ids;configuration=$c;expected_exit=0;completion_inferred=$false}
 Invoke-Command -Session $session -ArgumentList $stage,$task,$workerSha -ScriptBlock {param($Stage,$Task,$Sha) Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$path=Join-Path $Stage 'wrapper.ps1';if((Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant()-cne$Sha-or@(Get-ScheduledTask|Where-Object TaskName -CEQ $Task).Count){throw 'Fresh pinned worker task required.'};Register-ScheduledTask -TaskName $Task -Action (New-ScheduledTaskAction -Execute "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Argument ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$path+'"')) -Principal (New-ScheduledTaskPrincipal -UserId SYSTEM -LogonType ServiceAccount -RunLevel Highest) -Settings (New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero))|Out-Null;$t=Get-ScheduledTask -TaskName $Task;$i=$t|Get-ScheduledTaskInfo;if($t.State.ToString()-cne'Ready'-or$i.LastRunTime.Year-ge2000-or(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant()-cne$Sha-or@(Get-ScheduledTask|Where-Object {$_.TaskName-like'N2R-*'-and$_.State.ToString()-notin@('Ready','Disabled')}).Count){throw 'Only untouched one-shot SYSTEM worker may start.'};Start-ScheduledTask -TaskName $Task}
 Save 'start.json' @{start_issued_once=$true;completion_inferred=$false};Write-Output ('Started '+$task+'; host archive '+$root)
 $phase='waiting-owned-worker'
 do{$status=Invoke-Command -Session $session -ArgumentList $task -ScriptBlock {param($Task) $t=Get-ScheduledTask -TaskName $Task;$i=$t|Get-ScheduledTaskInfo;@{state=$t.State.ToString();last_result=$i.LastTaskResult;has_run=($i.LastRunTime.Year-ge2000)}};if(-not($status.has_run-and$status.state-in@('Ready','Disabled'))){Start-Sleep -Seconds 2}}while(-not($status.has_run-and$status.state-in@('Ready','Disabled')))
 HostGuard;$phase='closed-metadata-archive'
 $closed=Invoke-Command -Session $session -ArgumentList $stage,$task -ScriptBlock {param($Stage,$Task)
  Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$t=Get-ScheduledTask -TaskName $Task;$i=$t|Get-ScheduledTaskInfo
  if($t.State.ToString()-notin@('Ready','Disabled')-or@(Get-ScheduledTask|Where-Object {$_.TaskName-like'N2R-*'-and$_.State.ToString()-notin@('Ready','Disabled')}).Count-or@(Get-CimInstance Win32_Process|Where-Object {$_.Name-match'\A(?:ntfs2refs(?:-.+)?|lab-.+)\.exe\z'}).Count){throw 'Positive terminal project-task/process closure required before archiving.'}
  $worker=Get-Content -LiteralPath (Join-Path $Stage 'worker-process.json') -Raw|ConvertFrom-Json;$live=@(Get-CimInstance Win32_Process -Filter ('ProcessId='+$worker.pid));if($live.Count-and([DateTimeOffset]$live[0].CreationDate).ToUnixTimeMilliseconds()-eq$worker.creation_ms){throw 'Actual wrapper PID/creation remains live.'}
  $script:pagedBaselineArchiveHeld=[Collections.Generic.List[IO.FileStream]]::new();$rows=@()
  foreach($file in Get-ChildItem -LiteralPath $Stage -File -Recurse -Force){if($file.Name-like'*.exe'){continue};if($file.Attributes-band[IO.FileAttributes]::ReparsePoint-or$file.Length-gt64MB){throw 'Archive only bounded ordinary closed metadata.'};$a=$file.Directory;while($null-ne$a){if($a.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Archive reparse ancestry.'};$a=$a.Parent};$f=[IO.File]::Open($file.FullName,'Open','Read','Read');$script:pagedBaselineArchiveHeld.Add($f);$h=[Security.Cryptography.SHA256]::Create();try{$sha=([BitConverter]::ToString($h.ComputeHash($f))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};$relative=$file.FullName.Substring($Stage.Length+1);$rows+=@{guest_path=$file.FullName;relative=$relative;bytes=$f.Length;sha256=$sha}}
  @{task_state=$t.State.ToString();task_result=$i.LastTaskResult;rows=$rows;source_offline=(Get-Disk -Number 1).IsOffline;source_readonly=(Get-Disk -Number 1).IsReadOnly}
 };Save 'closed-guest-index.json' $closed
 foreach($row in $closed.rows){$relative=[string]$row.relative;Need (-not[IO.Path]::IsPathRooted($relative)-and$relative-notmatch'(^|\\)\.\.($|\\)') 'Bounded archive-relative path required.';$destination=if($relative.StartsWith('full-baseline\',[StringComparison]::Ordinal)){Join-Path $root $relative}else{Join-Path (Join-Path $root 'closed-worker') $relative};Need ([IO.Path]::GetFullPath($destination).StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)-and-not(Test-Path -LiteralPath $destination)) 'New exact host archive target required.';$parent=Split-Path -Parent $destination;if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent|Out-Null};Copy-Item -LiteralPath $row.guest_path -FromSession $session -Destination $destination;Need ((Get-Item -LiteralPath $destination).Length-eq$row.bytes-and(Get-FileHash -LiteralPath $destination).Hash.ToLowerInvariant()-ceq$row.sha256) 'Closed metadata source/copy pin differs.';if($row.bytes-gt0){$null=OpenPinned $destination $row.sha256 64MB $false}else{$empty=[IO.File]::Open($destination,'Open','Read','Read');$held.Add($empty);Need ($empty.Length-eq0) 'Closed empty log length differs.'}}
 Invoke-Command -Session $session -ScriptBlock {foreach($f in $script:pagedBaselineArchiveHeld){$f.Dispose()};$script:pagedBaselineArchiveHeld.Clear()}
 Save 'archive.json' @{schema_version=1;kind='closed-paged-full-source-baseline-archive';source=$closed;original_guest_json_paths_preserved=$true;json_rewritten=$false;source_payload_writes_requested=0;automatic_retry_cleanup_restore=$false}
 Need ($closed.task_result-eq0-and$closed.source_offline-and$closed.source_readonly) 'Baseline worker did not complete successfully; closed failure evidence preserved without retry.'
 $manifestPath=Join-Path $root 'full-baseline\baseline-manifest.json';Need (Test-Path -LiteralPath $manifestPath) 'Closed complete baseline manifest absent.'
 Save 'result.json' @{schema_version=1;success=$true;kind='paged-full-source-baseline-host-result';source_checkpoint=$ExpectedParent;source_commit=$SourceCommit;manifest_path=$manifestPath;manifest_sha256=(Get-FileHash -LiteralPath $manifestPath).Hash.ToLowerInvariant();additional_directory_receipt_path=$AdditionalDirectoryReceiptPath;additional_directory_receipt_sha256=$AdditionalDirectoryReceiptSha256;source_left_excluded=$true;source_admitted=$false;certificate_issued=$false;journal_created=$false;conversion_executed=$false;utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'result.json') -Raw
}catch{if($created-and-not(Test-Path -LiteralPath (Join-Path $root 'host-failed.json'))){Save 'host-failed.json' @{schema_version=1;success=$false;phase=$phase;error=$_.Exception.ToString();automatic_retry_restore_cleanup=$false;worker_death_inferred=$false;utc=[DateTime]::UtcNow.ToString('o')}};throw}
finally{if($null-ne$session){Remove-PSSession $session -ErrorAction SilentlyContinue};foreach($f in $held){$f.Dispose()}}
